+    let a3 = align_from_axes(&w, "Setup1", &axes).expect("the 3D path");
+    let a2 = turn_in_plane(&w, "Setup1", &axes).expect("the in-plane path");
+    for (p, q) in [a3.pos.x, a3.pos.y, a3.pos.z]
+        .iter()
+        .zip([a2.pos.x, a2.pos.y, a2.pos.z])
+    {
+        assert!(
+            (p - q).abs() < TIGHT,
+            "positions match: {:?} vs {:?}",
